'use strict';
const assert = require('node:assert/strict');
const { createStore, createHayakuRuntime, createValidPacket } = require('./fixtures/hayaku_runtime_harness.cjs');
// Generated by the actual 3.0.57 plugin, not the current writer/hash implementation.
const legacy = require('./fixtures/hayaku_evidence_3_0_57.json');
const [manifestKey, manifest] = Object.entries(legacy.evidence).find(([key]) => key.includes('evidence_manifest.'));
const ref = { manifestKey, manifestHash: manifest.manifestHash, evidenceHash: manifest.evidenceHash };
const input = { scopeKey: manifest.scopeKey, recordId: manifest.recordId, pairIndex: manifest.pairIndex,
  user: 'Find ribbon.', assistant: 'Alice found a blue ribbon.',
  userCanonicalHash: manifest.userCanonicalHash, assistantCanonicalHash: manifest.assistantCanonicalHash };
const seed = () => { const store = createStore(); for (const [key, value] of Object.entries(legacy.evidence)) store.values.set(key, JSON.stringify(value)); return store; };
const evidenceSnapshot = store => Object.fromEntries([...store.values].filter(([key]) => key.startsWith('hayaku.v2.recovery_evidence_')));
const fixture = store => createHayakuRuntime({ pluginStorage: store, messages: structuredClone(legacy.messages), autoRepair: false });
const envelope = () => {
  const summary = input.assistant;
  const packet = createValidPacket({ turn: 2, subject: 'Alice', scene: 'archive', summary });
  packet.entity.characters = [{ name: 'Alice' }]; packet.planner.continuity_locks = [summary];
  const grounding = [];
  const walk = (value, base) => {
    if (Array.isArray(value)) { value.forEach((item, index) => { if (item != null && (typeof item !== 'string' || item.trim())) grounding.push({ path: `${base}[${index}]`, source: 'target', evidence: [summary] }); }); return; }
    if (value && typeof value === 'object') Object.entries(value).forEach(([key, nested]) => walk(nested, `${base}.${key}`));
  };
  for (const axis of ['entity', 'world', 'narrative', 'planner']) walk(packet[axis], axis);
  grounding.push({ path: 'meta.summary_memory.summary', source: 'target', evidence: [summary] });
  return { schema: 'hayaku.native_repair_output.v1', packet, grounding };
};
(async () => {
  const store = seed(), before = evidenceSnapshot(store);
  let rt = await fixture(store);
  try {
    assert.equal((await rt.hayaku._test.readRecoveryEvidenceSidecar(ref, input)).ok, true);
    for (let i = 0; i < 2; i++) {
      const reused = await rt.hayaku._test.writeRecoveryEvidenceSidecar(input);
      assert.equal(reused.ok, true, reused.reason);
      assert.equal(reused.manifestRef.manifestHash, ref.manifestHash);
      assert.equal(reused.manifest.pluginVersion, '3.0.57');
      assert.equal(reused.manifest.createdAt, manifest.createdAt);
      assert.deepEqual(evidenceSnapshot(store), before, 'reuse must preserve every original byte');
    }
    rt.setLlmResponder(async () => ({ type: 'success', result: JSON.stringify(envelope()) }));
    const repaired = await rt.hayaku.recovery.repairSelected({ scopeKey: input.scopeKey, targetTurns: [2] });
    assert.equal(repaired.ok, true, JSON.stringify(repaired));
    assert.equal(repaired.completed, 1);
    assert.equal(repaired.physicalCalls, 1);
    assert.equal(rt.llmCalls.length, 1);
    const ledger = await rt.hayaku.ledger.inspect({ includeRecords: true });
    assert(ledger.records.some(row => row.packetType === 'recovery_snapshot' && row.recordState === 'active' && Number(row.targetPairIndex) === 2));
    assert.deepEqual(evidenceSnapshot(store), before, 'manual repair must not replace legacy evidence');
  } finally { await rt.dispose(); }
  rt = await fixture(store);
  try {
    assert.equal((await rt.hayaku._test.readRecoveryEvidenceSidecar(ref, input)).ok, true, 'legacy references survive reload');
    const ledger = await rt.hayaku.ledger.inspect({ includeRecords: true });
    assert(ledger.records.some(row => row.packetType === 'recovery_snapshot' && row.recordState === 'active' && Number(row.targetPairIndex) === 2), 'recovered packet survives reload');
  } finally { await rt.dispose(); }

  for (const [label, mutate, reason] of [
    ['invalid manifest hash', s => { const m = structuredClone(manifest); m.manifestHash = 'corrupt'; s.values.set(manifestKey, JSON.stringify(m)); }, /manifest_write_failed:key_collision/],
    ['corrupt body', s => { const key = manifest.roles.user.chunks[0].key, c = JSON.parse(s.values.get(key)); c.body = 'Different source'; s.values.set(key, JSON.stringify(c)); }, /chunk_write_failed:key_collision/],
    ['corrupt chunk length', s => { const key = manifest.roles.user.chunks[0].key, c = JSON.parse(s.values.get(key)); c.bodyChars++; s.values.set(key, JSON.stringify(c)); }, /chunk_invalid:user:0/]
  ]) {
    const broken = seed(); mutate(broken); const snapshot = evidenceSnapshot(broken); rt = await fixture(broken);
    try { const result = await rt.hayaku._test.writeRecoveryEvidenceSidecar(input); assert.equal(result.ok, false, label); assert.match(result.reason, reason, label); assert.deepEqual(evidenceSnapshot(broken), snapshot, label); assert.equal(rt.llmCalls.length, 0); }
    finally { await rt.dispose(); }
  }
  for (const altered of [{ userCanonicalHash: 'changed-provenance' }, { pairIndex: 3 }, { scopeKey: 'foreign-scope' }, { recordId: 'foreign-record' }]) {
    // A validly hashed but semantically different manifest must still be rejected.
    const fresh = createStore(); rt = await fixture(fresh); let different;
    try { different = await rt.hayaku._test.writeRecoveryEvidenceSidecar({ ...input, ...altered }); assert(different.ok); }
    finally { await rt.dispose(); }
    const conflict = seed(); conflict.values.set(manifestKey, JSON.stringify(different.manifest)); const snapshot = evidenceSnapshot(conflict); rt = await fixture(conflict);
    try { const result = await rt.hayaku._test.writeRecoveryEvidenceSidecar(input); assert.equal(result.reason, 'recovery_evidence_manifest_write_failed:key_collision'); assert.deepEqual(evidenceSnapshot(conflict), snapshot); }
    finally { await rt.dispose(); }
  }
  rt = await fixture(seed());
  try {
    const changed = await rt.hayaku._test.writeRecoveryEvidenceSidecar({ ...input, user: 'Changed visible source.' });
    assert(changed.ok); assert.notEqual(changed.manifestRef.manifestKey, manifestKey);
    assert.equal((await rt.hayaku._test.readRecoveryEvidenceSidecar(ref, input)).ok, true);
  } finally { await rt.dispose(); }
  console.log('PASS legacy manifest reuse, repeat/reload, manual repair durable commit, corrupt/foreign/provenance rejection, original preservation, new source isolation');
})().catch(error => { console.error(error); process.exitCode = 1; });
